# if rpm -q --quiet "gdm" ; then
# dnf remove -y --noautoremove "gdm"
# fi

# else
#     >&2 echo 'Remediation is not applicable, nothing was done'
# fi

# ) 

# END fix for 'xccdf_org.ssgproject.content_rule_package_gdm_removed'
(>&2 echo "Undoing rule: 'xccdf_org.ssgproject.content_rule_package_gdm_removed' and re-activating audit rule for gdm"); (

# Install gdm if not installed
if ! rpm -q --quiet "gdm"; then
    dnf install -y "gdm"
else
    echo "gdm is already installed"
fi

# Ensure all dependencies for gdm are installed
dnf deplist gdm | awk '/provider:/ {print $2}' | sort -u | xargs -r dnf install -y



# Enable and start gdm service
systemctl enable gdm
systemctl start gdm

# Remove any 'never' audit rules for gdm to ensure auditing is not disabled
if grep -E '^-a never,.*gdm' /etc/audit/rules.d/*.rules 2>/dev/null; then
    sed -i '/-a never,.*gdm/d' /etc/audit/rules.d/*.rules
    echo "Removed 'never' audit rules for gdm."
fi

# Restore the audit rule for gdm (example rule, adjust as needed)
AUDIT_RULE='-w /usr/sbin/gdm -p x -k gdm'

# Check if the rule is already present
if ! grep -qF "$AUDIT_RULE" /etc/audit/rules.d/*.rules 2>/dev/null; then
    echo "$AUDIT_RULE" >> /etc/audit/rules.d/gdm.rules
    echo "Audit rule for gdm added."
else
    echo "Audit rule for gdm already present."
fi

# Reload audit rules
augenrules --load || service auditd restart

echo "gdm package, dependencies, service, and audit rule are now active."
)
# END fix for 'xccdf_org.ssgproject.content_rule_package_gdm_removed'

